import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.CpZKh-tG.js";const u=JSON.parse('{"title":"Panorama redesign — visual anchor mockups","description":"","frontmatter":{},"headers":[],"relativePath":"mockups/panorama-redesign/README.md","filePath":"mockups/panorama-redesign/README.md"}'),n={name:"mockups/panorama-redesign/README.md"};function s(i,t,d,c,l,h){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="panorama-redesign-—-visual-anchor-mockups" tabindex="-1">Panorama redesign — visual anchor mockups <a class="header-anchor" href="#panorama-redesign-—-visual-anchor-mockups" aria-label="Permalink to &quot;Panorama redesign — visual anchor mockups&quot;">​</a></h1><p>8 PNG frames at 1920×1080 showing the proposed Tier-3 panorama redesign for issue <a href="https://github.com/chipi/orrery/issues/286" target="_blank" rel="noreferrer">#286</a> / PRD-022 / ADR-074.</p><p>Each frame is a Playwright-rendered HTML page that composites the existing 4096×2048 equirectangular panorama JPEG (cropped to a typical ~60° FOV slice) as background, then overlays schematic SVG of the proposed UI: caption box, compass rose, annotation pins, &quot;this region not photographed&quot; microcopy, cycler arrows for multi-pano sites, cross-link footer.</p><p>Backgrounds use <code>static/images/hotspots/&lt;body&gt;/&lt;site&gt;/tier3-pan.jpg</code> directly — the panorama itself is the visual anchor; the SVG drawn on top shows what the <strong>new</strong> UI brings to that same view.</p><h2 id="frame-inventory" tabindex="-1">Frame inventory <a class="header-anchor" href="#frame-inventory" aria-label="Permalink to &quot;Frame inventory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>File</th><th>Site</th><th>Agency</th><th>Demonstrates</th></tr></thead><tbody><tr><td>01</td><td><code>01-apollo11.png</code></td><td>Apollo 11</td><td>NASA</td><td>Caption + compass + annotation pins (LM Eagle, U.S. flag, Buzz shadow) + cross-link</td></tr><tr><td>02</td><td><code>02-apollo17.png</code></td><td>Apollo 17</td><td>NASA</td><td>South Massif + Camelot Crater annotations + LRV pin</td></tr><tr><td>03</td><td><code>03-curiosity-with-cycler.png</code></td><td>Curiosity</td><td>NASA</td><td>Multi-pano cycler (&quot;Sol 3573 · 4 panoramas at this site&quot;) + Vera Rubin / Mt. Sharp / drill-site annotations</td></tr><tr><td>04</td><td><code>04-perseverance.png</code></td><td>Perseverance</td><td>NASA</td><td>Ingenuity / sample tubes / Jezero rim annotations + audio cross-link</td></tr><tr><td>05</td><td><code>05-change4.png</code></td><td>Chang&#39;e 4</td><td>CNSA</td><td>First-lunar-farside framing + Yutu-2 / Von Kármán crater annotations</td></tr><tr><td>06</td><td><code>06-chandrayaan3.png</code></td><td>Chandrayaan-3</td><td>ISRO</td><td>First-south-pole framing + Pragyan rover annotation</td></tr><tr><td>07</td><td><code>07-mars3-honest-artifact.png</code></td><td>Mars 3</td><td>USSR</td><td><strong>Honest synthetic-artifact treatment</strong> — most of the &quot;panorama&quot; is synthetic fill honouring the 14.5 s historical fragment</td></tr><tr><td>08</td><td><code>08-perseverance-look-up-synthetic.png</code></td><td>Perseverance</td><td>NASA</td><td><strong>Free-pitch honesty</strong> — camera pitched up past +15° fires synthetic-region microcopy</td></tr></tbody></table><h2 id="regenerate" tabindex="-1">Regenerate <a class="header-anchor" href="#regenerate" aria-label="Permalink to &quot;Regenerate&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/mockups/render-panorama-redesign.mjs</span></span></code></pre></div><p>Outputs the 8 frames into this directory. Idempotent — temp <code>_bg_*.jpg</code> and <code>_*.html</code> files are cleaned up automatically.</p><h2 id="design-decisions-visible-in-the-mockups" tabindex="-1">Design decisions visible in the mockups <a class="header-anchor" href="#design-decisions-visible-in-the-mockups" aria-label="Permalink to &quot;Design decisions visible in the mockups&quot;">​</a></h2><ul><li><strong>Caption box bottom-left</strong> — sol/date/instrument header, body caption, credit footer; agency-coloured left border.</li><li><strong>Compass rose top-right</strong> — circular, N/E/S/W marks, agency-gold N-arrow rotating with yaw (frame 7 shows the arrow at 0° as a baseline).</li><li><strong>Annotation pins</strong> — blue agency-tinted circle + downward triangle + label box. Click target (in implementation) is the pin glyph; label box is hover/tap state.</li><li><strong>Cycler arrows + counter</strong> — only visible when <code>panorama_set.length &gt; 1</code> (frame 3). Counter format: <code>&lt;current label&gt; · N panoramas at this site</code>.</li><li><strong>Cross-link footer</strong> — slim bottom-right strip of agency-styled link chips. Hints: <code>↗</code> for navigation, <code>♪</code> for audio episode.</li><li><strong>Synthetic-region microcopy</strong> — dashed-border centred banner. Fires when camera pitches into a declared synthetic region (frame 7 = entire view synthetic; frame 8 = looking up past Mastcam-Z&#39;s +15° coverage).</li><li><strong>Exit button top-left</strong> — <code>RETURN TO ORBIT · ESC</code> strip, slightly more affordance than the current Tier-3 implementation (today it&#39;s button-only with no kbd shortcut hint).</li></ul><h2 id="what-the-mockups-are-not" tabindex="-1">What the mockups are NOT <a class="header-anchor" href="#what-the-mockups-are-not" aria-label="Permalink to &quot;What the mockups are NOT&quot;">​</a></h2><ul><li><strong>Not pixel-perfect</strong> — agency colours, exact spacing, font weights will be polished in Phase 2.</li><li><strong>Not a contract for source-image quality</strong> — Phase 1 may re-source higher-res panoramas where available (Curiosity, Perseverance especially). Current backgrounds are the 4 K assets in repo today.</li><li><strong>Not annotation curation</strong> — the annotation labels in these frames are illustrative (&quot;Vera Rubin Ridge&quot;, &quot;Ingenuity helicopter&quot;). Phase 4 curates the real per-site annotation lists.</li><li><strong>Not the full feature list</strong> — fullscreen + deep-link share + auto-tour (Phase 3) aren&#39;t visualised here.</li></ul><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><p>Script: <code>scripts/mockups/render-panorama-redesign.mjs</code> PRD: <a href="./../../prd/PRD-022">PRD-022</a> ADR: <a href="./../../adr/ADR-074">ADR-074</a> Issue: <a href="https://github.com/chipi/orrery/issues/286" target="_blank" rel="noreferrer">#286</a></p>',15)])])}const g=e(n,[["render",s]]);export{u as __pageData,g as default};
